 RUL.append(dict(id=id,priority=10,when=w,action=dict(type=t,components=['ceritinib'],message=msg,recommendation=msg,dose_calculation='specialist_review',show_in_dose_actions=True),source=dict(document='NCCP 00340 v4' if source=='nccp' else 'EMA Zykadia SmPC',url=N if source=='nccp' else S,page=str(page)),explanation=msg))
